let activeLanguage = 'en';
export const getActiveLanguage = () => activeLanguage;
const dynamicPhrases = [
  [/^Signed as (.+)$/i, 'Signé en tant que $1', 'Signed as $1'],
  [/^Joined (.+)$/i, 'Inscrit le $1', 'Joined $1'],
  [/^Paid (.+)$/i, 'Payé le $1', 'Paid $1'],
  [/^Signed (.+)$/i, 'Signé le $1', 'Signed $1'],
  [/^Published (.+)$/i, 'Publié le $1', 'Published $1'],
  [/^Created (.+)$/i, 'Créé le $1', 'Created $1'],
  [/^Earned after full payment$/i, 'Acquise après paiement intégral', 'Earned after full payment'],
];

function translateValue(value, language, reverseTranslations) {
  if (language === 'fr') {
    if (translations[value]) return translations[value];
    const clients = value.match(/^(\d+) clients?$/i);
    if (clients) return `${clients[1]} client${clients[1] === '1' ? '' : 's'}`;
    for (const [pattern, french] of dynamicPhrases) {
      if (pattern.test(value)) return value.replace(pattern, french);
    }
  } else {
    if (reverseTranslations[value]) return reverseTranslations[value];
    for (const [pattern, , english] of dynamicPhrases) {
      if (pattern.test(value)) return value.replace(pattern, english);
    }
  }
  return null;
}

export function useLanguage() {
  const [language, setLanguage] = useState(() => localStorage.getItem('monata-language') === 'fr' ? 'fr' : 'en');
  useEffect(() => {
    activeLanguage = language;
    localStorage.setItem('monata-language', language);
    document.documentElement.lang = language;
    const reverseTranslations = Object.fromEntries(Object.entries(translations).map(([english, french]) => [french, english]));
    const pageTitle = 'Monata Global Services | Work, moving forward';
    document.title = language === 'fr' ? (translations[pageTitle] || pageTitle) : pageTitle;
    const translate = () => {
      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      let node;
      while ((node = walker.nextNode())) {
        const original = node.nodeValue;
        const key = original?.trim();
        const replacement = key && translateValue(key, language, reverseTranslations);
        if (key && replacement && replacement !== key) node.nodeValue = original.replace(key, replacement);
      }
      document.querySelectorAll('[placeholder],[aria-label],[title],[alt]').forEach((element) => {
        for (const attribute of ['placeholder', 'aria-label', 'title', 'alt']) {
          const value = element.getAttribute(attribute);
          const replacement = value && translateValue(value, language, reverseTranslations);
          if (value && replacement && replacement !== value) element.setAttribute(attribute, replacement);
        }
      });
      document.querySelectorAll('meta[name="description"],meta[name="twitter:description"],meta[name="twitter:title"],meta[property="og:description"],meta[property="og:title"],meta[property="og:image:alt"]').forEach((element) => {
        const content = element.getAttribute('content');
        const replacement = content && translateValue(content, language, reverseTranslations);
        if (replacement && replacement !== content) element.setAttribute('content', replacement);
      });
    };
    translate();
    const observer = new MutationObserver(translate);
    observer.observe(document.body, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [language]);
  return [language, (next) => setLanguage(next)];
}
